import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { clone as cloneSkeleton } from "three/addons/utils/SkeletonUtils.js";

/**
 * Reusable GPU & Modular Skinned Cloth Physics System for Kaliyugham
 * ---------------------------------------------------------------------------
 * Loads standalone cloth GLBs generated by `scripts/generate_kerala_cloths.py`
 * (stored in `public/models/cloths/*.glb`) and supports BOTH:
 *
 *   1. Bone-attached & world cloths (`attachClothToBone`, `placeWorldCloth`):
 *      Melmundu, Thorthu, Kacha sash tail, clotheslines, market awnings, temple flags.
 *
 *   2. RDR2 / GTA V-style Modular Skinned Garments (`attachSkinnedClothToActor`):
 *      Skinned Mundu GLBs (`cloth_mundu_*_skinned.glb`) weighted to the master
 *      Mixamo skeleton. At runtime, vertices are aligned to the target NPC's exact
 *      rest pose, skin indices are remapped to the NPC's live Mixamo bones, and
 *      the garment is bound directly to the NPC's live Skeleton — giving zero
 *      leg-clipping during stride PLUS live GPU wind flutter on the bottom hem!
 */

export type KeralaClothKey =
  | "cloth_thorthu_shoulder"
  | "cloth_melmundu_kasavu"
  | "cloth_kacha_sash_tail"
  | "cloth_mundu_kasavu"
  | "cloth_mundu_kalli"
  | "cloth_mundu_kasavu_skinned"
  | "cloth_mundu_kalli_skinned"
  | "cloth_mundu_folded_skinned"
  | "cloth_hanging_laundry"
  | "cloth_market_awning"
  | "cloth_temple_flag";

export interface ClothPhysicsParams {
  windAmp?: number;
  flutterFreq?: number;
  gravitySag?: number;
  dragStrength?: number;
}

export interface ClothInstance {
  group: THREE.Object3D;
  setVelocity: (vx: number, vz: number) => void;
  setWindScale: (scale: number) => void;
  dispose: () => void;
}

interface ClothShaderUniforms {
  uTime: { value: number };
  uWindStrength: { value: number };
  uWindAmp: { value: number };
  uFlutterFreq: { value: number };
  uGravitySag: { value: number };
  uDispScale: { value: number };
  uVelocity: { value: THREE.Vector3 };
}

const loader = new GLTFLoader();
const templateCache = new Map<string, Promise<THREE.Group>>();
const activeUniforms = new Set<ClothShaderUniforms>();

function sanitizeBoneName(name: string): string {
  return name.replace(/^mixamorig\d*[:_]?/i, "mixamorig").toLowerCase();
}

function loadClothTemplate(
  baseUrl: string,
  key: KeralaClothKey,
  preserveSkinning = false,
): Promise<THREE.Group> {
  const url = `${baseUrl}models/cloths/${key}.glb`;
  let promise = templateCache.get(url);
  if (!promise) {
    promise = new Promise<THREE.Group>((resolve, reject) => {
      loader.load(url, (gltf) => resolve(gltf.scene), undefined, reject);
    });
    templateCache.set(url, promise);
  }
  return promise.then((tpl) =>
    preserveSkinning ? (cloneSkeleton(tpl) as THREE.Group) : tpl.clone(true),
  );
}

function buildClothPinAttribute(geom: THREE.BufferGeometry): THREE.BufferGeometry {
  const cloned = geom.clone();
  const pos = cloned.attributes.position as THREE.BufferAttribute;
  const count = pos.count;
  const pinData = new Float32Array(count * 3);

  // Blender writes our ClothPin attribute to COLOR_1 (color_1) when a default COLOR_0 exists
  const srcAttr =
    (cloned.attributes.color_1 as THREE.BufferAttribute | undefined) ??
    (cloned.attributes.color as THREE.BufferAttribute | undefined);

  let hasVariation = false;
  if (srcAttr) {
    for (let i = 0; i < count; i++) {
      const r = srcAttr.getX(i);
      const g = srcAttr.getY(i);
      const b = srcAttr.getZ(i);
      if (r < 0.98) hasVariation = true;
      pinData[i * 3] = r;
      pinData[i * 3 + 1] = g;
      pinData[i * 3 + 2] = b;
    }
  }

  // Fallback if an imported cloth mesh lacks a pin color channel: pin top Y vertices
  if (!hasVariation) {
    cloned.computeBoundingBox();
    const bb = cloned.boundingBox!;
    const h = Math.max(0.01, bb.max.y - bb.min.y);
    for (let i = 0; i < count; i++) {
      const normY = (pos.getY(i) - bb.min.y) / h;
      const pin = normY > 0.85 ? 1.0 : Math.max(0, normY * normY);
      pinData[i * 3] = pin;
      pinData[i * 3 + 1] = (pos.getX(i) - bb.min.x) / Math.max(0.01, bb.max.x - bb.min.x);
      pinData[i * 3 + 2] = 1.0 - pin;
    }
  }

  cloned.setAttribute("aClothPin", new THREE.BufferAttribute(pinData, 3));
  // Strip raw color attributes so MeshStandardMaterial never multiplies albedo by pin mask
  cloned.deleteAttribute("color");
  cloned.deleteAttribute("color_1");
  return cloned;
}

function patchClothMaterial(
  mat: THREE.MeshStandardMaterial,
  uniforms: ClothShaderUniforms,
): THREE.MeshStandardMaterial {
  const cloned = mat.clone();
  cloned.side = THREE.DoubleSide;
  cloned.vertexColors = false;
  cloned.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = uniforms.uTime;
    shader.uniforms.uWindStrength = uniforms.uWindStrength;
    shader.uniforms.uWindAmp = uniforms.uWindAmp;
    shader.uniforms.uFlutterFreq = uniforms.uFlutterFreq;
    shader.uniforms.uGravitySag = uniforms.uGravitySag;
    shader.uniforms.uDispScale = uniforms.uDispScale;
    shader.uniforms.uVelocity = uniforms.uVelocity;

    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        `#include <common>
        attribute vec3 aClothPin;
        uniform float uTime;
        uniform float uWindStrength;
        uniform float uWindAmp;
        uniform float uFlutterFreq;
        uniform float uGravitySag;
        uniform float uDispScale;
        uniform vec3 uVelocity;`,
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
        float clothPin = clamp(aClothPin.x, 0.0, 1.0);
        float clothFree = 1.0 - clothPin;
        float clothPhase = aClothPin.y * 6.2831853;
        float freedom = pow(clothFree, 1.55);

        // Normalize spatial frequency to meters regardless of FBX cm vs GLB m rest scale
        vec3 posM = position / max(uDispScale, 0.0001);

        // Multi-frequency traveling cotton wave + monsoon wind gusts
        float t = uTime * uFlutterFreq;
        float waveMain = sin(t - posM.x * 5.2 + posM.y * 4.4 + clothPhase);
        float waveRipple = cos(t * 1.85 - posM.x * 9.5 - posM.y * 7.2 + clothPhase * 1.7);
        float gust = (0.72 + 0.42 * sin(uTime * 0.95 + clothPhase * 0.5)) * uWindStrength;

        // Billow strongly along cloth normal (Z) with lateral sway (X) and subtle lift (Y)
        float billowZ = (waveMain * 0.72 + waveRipple * 0.28 + 0.30) * uWindAmp * gust * freedom;
        float swayX = (cos(t * 0.85 + posM.y * 3.5 + clothPhase) * 0.45) * uWindAmp * gust * freedom;
        float liftY = (waveRipple * 0.28 * uWindAmp * gust - uGravitySag) * freedom;

        // Character movement inertia drag (cloth trails backward opposite to walk/run velocity)
        vec3 dragDisp = -uVelocity * (0.11 * freedom);

        transformed.x += (swayX + dragDisp.x) * uDispScale;
        transformed.y += liftY * uDispScale;
        transformed.z += (billowZ + dragDisp.z) * uDispScale;`,
      );
  };
  cloned.customProgramCacheKey = () => "kaliyugham-gpu-cloth-v3";
  return cloned;
}

/**
 * Loads a standalone Kerala cloth GLB and equips it with GPU cloth physics.
 */
export async function createClothInstance(
  baseUrl: string,
  key: KeralaClothKey,
  params: ClothPhysicsParams = {},
): Promise<ClothInstance> {
  const group = await loadClothTemplate(baseUrl, key, false);

  const uniforms: ClothShaderUniforms = {
    uTime: { value: 0 },
    uWindStrength: { value: 1.0 },
    uWindAmp: { value: params.windAmp ?? 0.14 },
    uFlutterFreq: { value: params.flutterFreq ?? 4.2 },
    uGravitySag: { value: params.gravitySag ?? 0.015 },
    uDispScale: { value: 1.0 },
    uVelocity: { value: new THREE.Vector3() },
  };
  activeUniforms.add(uniforms);

  const dragStrength = params.dragStrength ?? 1.0;
  const createdMaterials: THREE.Material[] = [];
  const createdGeometries: THREE.BufferGeometry[] = [];

  group.traverse((obj) => {
    if (!(obj instanceof THREE.Mesh)) return;
    const clothGeom = buildClothPinAttribute(obj.geometry);
    createdGeometries.push(clothGeom);
    obj.geometry = clothGeom;
    obj.castShadow = true;
    obj.receiveShadow = true;
    obj.frustumCulled = false;

    const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
    const nextMats = mats.map((m) => {
      if (m instanceof THREE.MeshStandardMaterial) {
        const patched = patchClothMaterial(m, uniforms);
        createdMaterials.push(patched);
        return patched;
      }
      return m;
    });
    obj.material = Array.isArray(obj.material) ? nextMats : nextMats[0];
  });

  return {
    group,
    setVelocity: (vx: number, vz: number) => {
      uniforms.uVelocity.value.set(vx * dragStrength, 0, vz * dragStrength);
    },
    setWindScale: (scale: number) => {
      uniforms.uWindStrength.value = scale;
    },
    dispose: () => {
      activeUniforms.delete(uniforms);
      for (const m of createdMaterials) m.dispose();
      for (const g of createdGeometries) g.dispose();
    },
  };
}

function getSkeletonRestBonePosition(
  skeleton: THREE.Skeleton,
  sanitizedTargetName: string,
): THREE.Vector3 | null {
  for (let i = 0; i < skeleton.bones.length; i++) {
    if (sanitizeBoneName(skeleton.bones[i].name) === sanitizedTargetName) {
      const inv = skeleton.boneInverses[i];
      if (!inv) return null;
      const restMat = inv.clone().invert();
      return new THREE.Vector3().setFromMatrixPosition(restMat);
    }
  }
  return null;
}

/**
 * RDR2 / GTA V-style Modular Skinned-Cloth Binder:
 * Loads a Mixamo-weighted cloth GLB (e.g. `cloth_mundu_kasavu_skinned`),
 * aligns its rest-pose vertices to the target NPC's exact skeleton scale/hips,
 * remaps skin indices 1:1 onto the NPC's live Mixamo bones, and binds it directly
 * to the NPC's live Skeleton with GPU hem physics on top!
 */
export async function attachSkinnedClothToActor(
  baseUrl: string,
  key: KeralaClothKey,
  targetModel: THREE.Object3D,
  params: ClothPhysicsParams = {},
): Promise<ClothInstance | null> {
  // Find primary target SkinnedMesh on the NPC
  let targetMesh: THREE.SkinnedMesh | undefined;
  targetModel.traverse((obj) => {
    if (obj instanceof THREE.SkinnedMesh && obj.skeleton) {
      if (
        !targetMesh ||
        obj.geometry.attributes.position.count > targetMesh.geometry.attributes.position.count
      ) {
        targetMesh = obj;
      }
    }
  });
  if (!targetMesh || !targetMesh.skeleton) return null;

  const clothScene = await loadClothTemplate(baseUrl, key, true);
  let srcSkinned: THREE.SkinnedMesh | undefined;
  clothScene.traverse((obj) => {
    if (!srcSkinned && obj instanceof THREE.SkinnedMesh && obj.skeleton) {
      srcSkinned = obj;
    }
  });
  if (!srcSkinned || !srcSkinned.skeleton) return null;

  const targetSkel = targetMesh.skeleton;
  const srcSkel = srcSkinned.skeleton;

  // Build map: sanitized Mixamo bone name -> index inside targetSkel.bones
  const targetBoneIndexMap = new Map<string, number>();
  let fallbackHipsIdx = 0;
  for (let i = 0; i < targetSkel.bones.length; i++) {
    const nm = sanitizeBoneName(targetSkel.bones[i].name);
    targetBoneIndexMap.set(nm, i);
    if (nm === "mixamorigHips".toLowerCase()) fallbackHipsIdx = i;
  }

  // Compute exact target waist & leg span directly from the target NPC's Mixamo skeleton bind pose
  // (immune to any 0.01 cm-to-m Armature scale baked into Blender's exported cloth GLB!)
  const tgtHips = getSkeletonRestBonePosition(targetSkel, "mixamorighips") ?? new THREE.Vector3(0, 0.95, 0);
  const tgtFoot =
    getSkeletonRestBonePosition(targetSkel, "mixamorigleftfoot") ??
    getSkeletonRestBonePosition(targetSkel, "mixamorigleftleg") ??
    new THREE.Vector3(0, 0.08, 0);
  const tgtLegSpan = Math.max(0.1, Math.abs(tgtHips.y - tgtFoot.y));
  const isFolded = key.includes("folded");
  const desiredMunduH = tgtLegSpan * (isFolded ? 0.68 : 1.02);
  const desiredWaistY = tgtHips.y + tgtLegSpan * 0.05;

  const clothGeom = buildClothPinAttribute(srcSkinned.geometry);

  // Measure the cloth's own upright Y-up bounding box (waist = max.y, hem = min.y)
  const posAttr = clothGeom.attributes.position as THREE.BufferAttribute;
  clothGeom.computeBoundingBox();
  const srcBB = clothGeom.boundingBox!;
  const srcH = Math.max(0.001, srcBB.max.y - srcBB.min.y);
  const srcCenterX = (srcBB.min.x + srcBB.max.x) * 0.5;
  const srcCenterZ = (srcBB.min.z + srcBB.max.z) * 0.5;
  const srcTopY = srcBB.max.y;

  const scaleFactor = desiredMunduH / srcH;

  // Align cloth vertices directly into targetSkinnedMesh local bind space
  const tmpV = new THREE.Vector3();
  const tgtBindInv = targetMesh.bindMatrixInverse;
  for (let i = 0; i < posAttr.count; i++) {
    tmpV.fromBufferAttribute(posAttr, i);
    tmpV.set(
      (tmpV.x - srcCenterX) * scaleFactor + tgtHips.x,
      (tmpV.y - srcTopY) * scaleFactor + desiredWaistY,
      (tmpV.z - srcCenterZ) * scaleFactor + tgtHips.z,
    );
    tmpV.applyMatrix4(tgtBindInv);
    posAttr.setXYZ(i, tmpV.x, tmpV.y, tmpV.z);
  }
  posAttr.needsUpdate = true;
  clothGeom.computeVertexNormals();
  clothGeom.computeBoundingBox();
  clothGeom.computeBoundingSphere();

  // Exact meters-to-local-geometry scale so GPU wind displacement is always in true real-world meters
  const finalGeomH = Math.max(0.01, clothGeom.boundingBox!.max.y - clothGeom.boundingBox!.min.y);
  const dispScale = finalGeomH / (isFolded ? 0.58 : 0.90);

  // Remap skinIndex from srcSkel bone indices -> targetSkel bone indices & ensure weights sum to 1.0
  const skinIdxAttr = clothGeom.attributes.skinIndex as THREE.BufferAttribute | undefined;
  const skinWAttr = clothGeom.attributes.skinWeight as THREE.BufferAttribute | undefined;
  if (skinIdxAttr) {
    const remapTable = new Uint16Array(srcSkel.bones.length);
    for (let i = 0; i < srcSkel.bones.length; i++) {
      const nm = sanitizeBoneName(srcSkel.bones[i].name);
      remapTable[i] = targetBoneIndexMap.get(nm) ?? fallbackHipsIdx;
    }
    const newSkinIdx = new Uint16Array(skinIdxAttr.count * 4);
    for (let i = 0; i < skinIdxAttr.count; i++) {
      const i0 = Math.min(remapTable.length - 1, Math.max(0, Math.round(skinIdxAttr.getX(i))));
      const i1 = Math.min(remapTable.length - 1, Math.max(0, Math.round(skinIdxAttr.getY(i))));
      const i2 = Math.min(remapTable.length - 1, Math.max(0, Math.round(skinIdxAttr.getZ(i))));
      const i3 = Math.min(remapTable.length - 1, Math.max(0, Math.round(skinIdxAttr.getW(i))));
      newSkinIdx[i * 4] = remapTable[i0];
      newSkinIdx[i * 4 + 1] = remapTable[i1];
      newSkinIdx[i * 4 + 2] = remapTable[i2];
      newSkinIdx[i * 4 + 3] = remapTable[i3];
      if (skinWAttr) {
        const w0 = skinWAttr.getX(i);
        const w1 = skinWAttr.getY(i);
        const w2 = skinWAttr.getZ(i);
        const w3 = skinWAttr.getW(i);
        const sum = w0 + w1 + w2 + w3;
        if (sum < 0.001) {
          newSkinIdx[i * 4] = fallbackHipsIdx;
          skinWAttr.setXYZW(i, 1, 0, 0, 0);
        } else if (Math.abs(sum - 1.0) > 0.01) {
          skinWAttr.setXYZW(i, w0 / sum, w1 / sum, w2 / sum, w3 / sum);
        }
      }
    }
    clothGeom.setAttribute("skinIndex", new THREE.Uint16BufferAttribute(newSkinIdx, 4));
    if (skinWAttr) skinWAttr.needsUpdate = true;
  }

  const uniforms: ClothShaderUniforms = {
    uTime: { value: 0 },
    uWindStrength: { value: 1.0 },
    uWindAmp: { value: params.windAmp ?? 0.045 },
    uFlutterFreq: { value: params.flutterFreq ?? 4.0 },
    uGravitySag: { value: params.gravitySag ?? 0.004 },
    uDispScale: { value: dispScale },
    uVelocity: { value: new THREE.Vector3() },
  };
  activeUniforms.add(uniforms);

  const dragStrength = params.dragStrength ?? 0.65;
  const createdMaterials: THREE.Material[] = [];
  const srcMats = Array.isArray(srcSkinned.material) ? srcSkinned.material : [srcSkinned.material];
  const nextMats = srcMats.map((m) => {
    if (m instanceof THREE.MeshStandardMaterial) {
      const patched = patchClothMaterial(m, uniforms);
      createdMaterials.push(patched);
      return patched;
    }
    return m;
  });

  const boundMesh = new THREE.SkinnedMesh(
    clothGeom,
    Array.isArray(srcSkinned.material) ? nextMats : nextMats[0],
  );
  boundMesh.name = `SkinnedCloth_${key}`;
  boundMesh.castShadow = true;
  boundMesh.receiveShadow = true;
  boundMesh.frustumCulled = false;
  // DetachedBindMode keeps bindMatrix locked to targetMesh's rest bindMatrix instead of
  // overwriting it with the NPC's live world position every frame (prevents mesh explosion!).
  boundMesh.bindMode = THREE.DetachedBindMode;

  const hostParent = targetMesh.parent ?? targetModel;
  hostParent.add(boundMesh);
  boundMesh.bind(targetSkel, targetMesh.bindMatrix.clone());

  return {
    group: boundMesh,
    setVelocity: (vx: number, vz: number) => {
      uniforms.uVelocity.value.set(vx * dragStrength, 0, vz * dragStrength);
    },
    setWindScale: (scale: number) => {
      uniforms.uWindStrength.value = scale;
    },
    dispose: () => {
      activeUniforms.delete(uniforms);
      boundMesh.parent?.remove(boundMesh);
      clothGeom.dispose();
      for (const m of createdMaterials) m.dispose();
    },
  };
}

/**
 * Attaches a standalone cloth GLB to an NPC bone (e.g. Shoulder, Spine2, Hips).
 */
export async function attachClothToBone(
  baseUrl: string,
  key: KeralaClothKey,
  bone: THREE.Object3D,
  options?: {
    position?: [number, number, number];
    rotation?: [number, number, number];
    scale?: number;
    physics?: ClothPhysicsParams;
  },
): Promise<ClothInstance> {
  const inst = await createClothInstance(baseUrl, key, options?.physics);
  if (options?.position) inst.group.position.set(...options.position);
  if (options?.rotation) inst.group.rotation.set(...options.rotation);
  if (options?.scale !== undefined) inst.group.scale.setScalar(options.scale);
  bone.add(inst.group);
  return inst;
}

/**
 * Places a standalone cloth GLB in the world (clothesline, temple flag, market awning).
 */
export async function placeWorldCloth(
  baseUrl: string,
  key: KeralaClothKey,
  parent: THREE.Object3D,
  position: [number, number, number],
  rotationY = 0,
  scale = 1,
  physics?: ClothPhysicsParams,
): Promise<ClothInstance> {
  const inst = await createClothInstance(baseUrl, key, physics);
  inst.group.position.set(...position);
  inst.group.rotation.y = rotationY;
  inst.group.scale.setScalar(scale);
  parent.add(inst.group);
  return inst;
}

/**
 * Advances GPU wind & flutter time for all active cloth instances (call once per frame).
 */
export function updateClothPhysics(elapsed: number, windStrength = 1.0): void {
  for (const u of activeUniforms) {
    u.uTime.value = elapsed;
    u.uWindStrength.value = windStrength;
  }
}
